-- -----------------------------------------------------------------------------
create table public.notifications (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references public.profiles (id) on delete cascade,
  kind       text not null,
  title      text not null,
  body       text,
  link       text,
  read_at    timestamptz,
  created_at timestamptz not null default now()
);

create index notifications_user_created_idx on public.notifications (user_id, created_at desc);


-- ===== migrations/0004_views.sql =====
-- =============================================================================
-- 0004_views.sql
-- Marks are derived, never duplicated: assignment marks live in
-- submissions.marks_obtained and quiz marks in quiz_attempts.score.
-- v_student_marks unions both. Ungraded submissions appear with obtained = null
-- so the UI can show "Pending"; they are excluded from totals.
-- security_invoker = true makes the view respect the caller's RLS.
-- =============================================================================

create or replace view public.v_student_marks
with (security_invoker = true)
as
  select
    s.student_id,
    a.course_id,
    'assignment'::text                                   as kind,
    a.id                                                 as item_id,
    a.title,
    case when s.graded_at is not null then s.marks_obtained end as obtained,
    a.max_marks                                          as max,
    s.graded_at,
    s.id                                                 as source_id
  from public.submissions s
  join public.assignments a on a.id = s.assignment_id
  union all
  select
    qa.student_id,
    q.course_id,
    'quiz'::text                                         as kind,
    q.id                                                 as item_id,
    q.title,
    qa.score                                             as obtained,
    (
      select coalesce(sum(qq.marks), 0)
      from public.quiz_questions qq
      where qq.quiz_id = q.id
    )::numeric(6, 2)                                     as max,
    qa.submitted_at                                      as graded_at,
    qa.id                                                as source_id
  from public.quiz_attempts qa
  join public.quizzes q on q.id = qa.quiz_id
  where qa.submitted_at is not null;

comment on view public.v_student_marks is
  'Unified marks per student: (student_id, course_id, kind, item_id, title, obtained, max, graded_at).';

grant select on public.v_student_marks to authenticated, service_role;


-- ===== migrations/0005_rls.sql =====
-- =============================================================================
-- 0005_rls.sql
-- Row Level Security on every table. The API performs explicit authorization
-- first; these policies are the second line of defense for any direct
-- Supabase client call (including Realtime subscriptions).
-- =============================================================================

do $$
declare
  t text;
begin
  foreach t in array array[
    'profiles', 'courses', 'course_teachers', 'enrollments', 'audit_log',
    'resources', 'assignments', 'submissions', 'quizzes', 'quiz_questions',
    'quiz_answers', 'quiz_attempts', 'announcements', 'announcement_reads',
    'chat_messages', 'complaints', 'notifications'
  ] loop
    execute format('alter table public.%I enable row level security', t);
    -- Anonymous visitors never touch application data.
    execute format('revoke all on table public.%I from anon', t);
  end loop;
end;
$$;

revoke all on public.v_student_marks from anon;

-- -----------------------------------------------------------------------------
-- profiles
-- -----------------------------------------------------------------------------
create policy profiles_select on public.profiles
  for select to authenticated
  using (public.can_view_profile(id));

create policy profiles_admin_update on public.profiles
  for update to authenticated
  using (public.is_admin())
  with check (public.is_admin());

-- -----------------------------------------------------------------------------
-- courses / course_teachers / enrollments
-- -----------------------------------------------------------------------------
create policy courses_select on public.courses
  for select to authenticated
  using (
    public.is_admin()
    or (not is_archived and (public.teaches(id) or public.is_enrolled(id)))
  );

create policy courses_admin_insert on public.courses
  for insert to authenticated
  with check (public.is_admin());

create policy courses_admin_update on public.courses
  for update to authenticated
  using (public.is_admin())
  with check (public.is_admin());

create policy course_teachers_select on public.course_teachers
  for select to authenticated
  using (public.is_course_member(course_id));

create policy course_teachers_admin_insert on public.course_teachers
  for insert to authenticated
  with check (public.is_admin());

create policy course_teachers_admin_delete on public.course_teachers
  for delete to authenticated
  using (public.is_admin());

create policy enrollments_select on public.enrollments
  for select to authenticated
  using (
    student_id = auth.uid()
    or public.is_admin()
    or public.teaches(course_id)
    or public.is_enrolled(course_id)
  );

create policy enrollments_admin_insert on public.enrollments
  for insert to authenticated
  with check (public.is_admin());

create policy enrollments_admin_delete on public.enrollments
  for delete to authenticated
  using (public.is_admin());

-- -----------------------------------------------------------------------------
-- audit_log: admins read; only the service role writes.
-- -----------------------------------------------------------------------------
create policy audit_log_admin_select on public.audit_log
  for select to authenticated
  using (public.is_admin());

-- -----------------------------------------------------------------------------
-- resources
-- -----------------------------------------------------------------------------
create policy resources_select on public.resources
  for select to authenticated
  using (public.is_course_member(course_id));

create policy resources_insert on public.resources
  for insert to authenticated
  with check (
    uploaded_by = auth.uid()
    and (public.is_admin() or public.teaches(course_id))
  );

create policy resources_delete on public.resources
  for delete to authenticated
  using (public.is_admin() or uploaded_by = auth.uid());

-- -----------------------------------------------------------------------------
-- assignments
-- -----------------------------------------------------------------------------
create policy assignments_select on public.assignments
  for select to authenticated
  using (public.is_course_member(course_id));

create policy assignments_insert on public.assignments
  for insert to authenticated
  with check (
    created_by = auth.uid()
    and (public.is_admin() or public.teaches(course_id))
  );

create policy assignments_update on public.assignments
  for update to authenticated
  using (public.is_admin() or public.teaches(course_id))
  with check (public.is_admin() or public.teaches(course_id));

create policy assignments_delete on public.assignments
  for delete to authenticated
  using (public.is_admin() or public.teaches(course_id));

-- -----------------------------------------------------------------------------
-- submissions: students see only their own; teachers see their courses.
-- -----------------------------------------------------------------------------
create policy submissions_select on public.submissions
  for select to authenticated
  using (
    student_id = auth.uid()
    or public.is_admin()
    or exists (
      select 1 from public.assignments a
      where a.id = assignment_id and public.teaches(a.course_id)
    )
  );

create policy submissions_student_insert on public.submissions
  for insert to authenticated
  with check (
    student_id = auth.uid()
    and public.auth_role() = 'student'
    and exists (
      select 1 from public.assignments a
      where a.id = assignment_id and public.is_enrolled(a.course_id)
    )
  );

create policy submissions_update on public.submissions
  for update to authenticated
  using (
    (student_id = auth.uid() and public.auth_role() = 'student')
    or public.is_admin()
    or exists (
      select 1 from public.assignments a
      where a.id = assignment_id and public.teaches(a.course_id)
    )
  )
  with check (
    (student_id = auth.uid() and public.auth_role() = 'student')
    or public.is_admin()
    or exists (
      select 1 from public.assignments a
      where a.id = assignment_id and public.teaches(a.course_id)
    )
  );

-- -----------------------------------------------------------------------------
-- quizzes / questions / answer keys / attempts
-- -----------------------------------------------------------------------------
create policy quizzes_select on public.quizzes
  for select to authenticated
  using (
    public.is_admin()
    or public.teaches(course_id)
    or (is_published and public.is_enrolled(course_id))
  );

create policy quizzes_insert on public.quizzes
  for insert to authenticated
  with check (
    created_by = auth.uid()
    and (public.is_admin() or public.teaches(course_id))
  );

create policy quizzes_update on public.quizzes
  for update to authenticated
  using (public.is_admin() or public.teaches(course_id))
  with check (public.is_admin() or public.teaches(course_id));

create policy quizzes_delete on public.quizzes
  for delete to authenticated
  using (public.is_admin() or public.teaches(course_id));

-- Students may only read the questions of a quiz they have already started.
create policy quiz_questions_select on public.quiz_questions
  for select to authenticated
  using (
    exists (
      select 1 from public.quizzes q
      where q.id = quiz_id
        and (
          public.is_admin()
          or public.teaches(q.course_id)
          or exists (
            select 1 from public.quiz_attempts qa
            where qa.quiz_id = q.id and qa.student_id = auth.uid()
          )
        )
    )
  );

create policy quiz_questions_write on public.quiz_questions
  for all to authenticated
  using (
    exists (
      select 1 from public.quizzes q
      where q.id = quiz_id and (public.is_admin() or public.teaches(q.course_id))
    )
  )
  with check (
    exists (
      select 1 from public.quizzes q
      where q.id = quiz_id and (public.is_admin() or public.teaches(q.course_id))
    )
  );

-- Answer keys: teachers of the course and admins only. Never students.
create policy quiz_answers_staff_only on public.quiz_answers
  for all to authenticated
  using (
    exists (
      select 1
      from public.quiz_questions qq
      join public.quizzes q on q.id = qq.quiz_id
      where qq.id = question_id and (public.is_admin() or public.teaches(q.course_id))
    )
  )
  with check (
    exists (
      select 1
      from public.quiz_questions qq
      join public.quizzes q on q.id = qq.quiz_id
      where qq.id = question_id and (public.is_admin() or public.teaches(q.course_id))
    )
  );

-- Attempts are created and graded by the API (service role) so students can
-- never write a score. Students read their own; staff read their courses.
create policy quiz_attempts_select on public.quiz_attempts
  for select to authenticated
  using (
    student_id = auth.uid()
    or public.is_admin()
    or exists (
      select 1 from public.quizzes q
      where q.id = quiz_id and public.teaches(q.course_id)
    )
  );

-- -----------------------------------------------------------------------------
-- announcements & read receipts
-- -----------------------------------------------------------------------------
create policy announcements_select on public.announcements
  for select to authenticated
  using (
    course_id is null
    or public.is_course_member(course_id)
  );

create policy announcements_insert on public.announcements
  for insert to authenticated
  with check (
    author_id = auth.uid()
    and (
      public.is_admin()
      or (course_id is not null and public.teaches(course_id))
    )
  );

create policy announcements_update on public.announcements
  for update to authenticated
  using (public.is_admin() or author_id = auth.uid())
  with check (
    public.is_admin()
    or (author_id = auth.uid() and course_id is not null and public.teaches(course_id))
  );

create policy announcements_delete on public.announcements
  for delete to authenticated
  using (public.is_admin() or author_id = auth.uid());

create policy announcement_reads_own on public.announcement_reads
  for all to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

-- -----------------------------------------------------------------------------
-- chat (also governs Realtime postgres_changes delivery)
-- -----------------------------------------------------------------------------
create policy chat_messages_select on public.chat_messages
  for select to authenticated
  using (public.is_course_member(course_id));

create policy chat_messages_insert on public.chat_messages
  for insert to authenticated
  with check (
    sender_id = auth.uid()
    and deleted_at is null
    and (public.teaches(course_id) or public.is_enrolled(course_id))
  );

create policy chat_messages_soft_delete on public.chat_messages
  for update to authenticated
  using (
    public.is_admin()
    or public.teaches(course_id)
    or (sender_id = auth.uid() and created_at > now() - interval '5 minutes')
  )
  with check (
    public.is_admin()
    or public.teaches(course_id)
    or sender_id = auth.uid()
  );

-- -----------------------------------------------------------------------------
-- complaints
-- -----------------------------------------------------------------------------
create policy complaints_select on public.complaints
  for select to authenticated
  using (raised_by = auth.uid() or public.is_admin());

create policy complaints_insert on public.complaints
  for insert to authenticated
  with check (
    raised_by = auth.uid()
    and public.auth_role() in ('student', 'teacher')
    and status = 'open'
  );

create policy complaints_update on public.complaints
  for update to authenticated
  using (public.is_admin() or raised_by = auth.uid())
  with check (public.is_admin() or raised_by = auth.uid());

-- -----------------------------------------------------------------------------
-- notifications: users read and acknowledge their own.
-- -----------------------------------------------------------------------------
create policy notifications_select_own on public.notifications
  for select to authenticated
  using (user_id = auth.uid());

create policy notifications_update_own on public.notifications
  for update to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

revoke update on public.notifications from authenticated;
grant update (read_at) on public.notifications to authenticated;



-- ===== migrations/0006_guards.sql =====
-- =============================================================================
-- 0006_guards.sql
-- Data-integrity triggers. They enforce business rules even if someone calls
-- Supabase directly with a user JWT. Writes performed by the API's service
-- role (auth.uid() is null) are trusted and skip the guards.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- profiles: email is owned by Supabase Auth and cannot drift.
-- -----------------------------------------------------------------------------
create or replace function public.guard_profile_update()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null then
    return new;
  end if;
  if new.id <> old.id or new.email <> old.email then
    raise exception 'Profile id and email cannot be changed' using errcode = '42501';
  end if;
  if new.id = auth.uid() and (new.role <> old.role or new.is_active <> old.is_active) then
    raise exception 'You cannot change your own role or status' using errcode = '42501';
  end if;
  return new;
end;
$$;

create trigger profiles_guard_update
  before update on public.profiles
  for each row execute function public.guard_profile_update();

-- -----------------------------------------------------------------------------
-- submissions: server-side lateness, deadline enforcement, grade protection.
-- -----------------------------------------------------------------------------
create or replace function public.guard_submission_write()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_assignment public.assignments%rowtype;
begin
  if auth.uid() is null then
    return new;
  end if;

  select * into v_assignment from public.assignments where id = new.assignment_id;
  if not found then
    raise exception 'Assignment not found' using errcode = '23503';
  end if;

  -- Student creating or replacing their own submission
  if public.auth_role() = 'student' and new.student_id = auth.uid() then
    if tg_op = 'UPDATE'
       and (new.assignment_id <> old.assignment_id or new.student_id <> old.student_id) then
      raise exception 'Submission ownership cannot change' using errcode = '42501';
    end if;
    if now() > v_assignment.due_at and not v_assignment.allow_late then
      raise exception 'The deadline for this assignment has passed' using errcode = 'P0001';
    end if;
    new.submitted_at   := now();
    new.is_late        := now() > v_assignment.due_at;
    -- Resubmission clears any previous grade.
    new.marks_obtained := null;
    new.feedback       := null;
    new.graded_by      := null;
    new.graded_at      := null;
    return new;
  end if;

  -- Staff grading
  if tg_op = 'INSERT' then
    raise exception 'Only students can create submissions' using errcode = '42501';
  end if;
  if new.assignment_id <> old.assignment_id
     or new.student_id <> old.student_id
     or new.text_answer is distinct from old.text_answer
     or new.file_path is distinct from old.file_path
     or new.file_name is distinct from old.file_name
     or new.submitted_at <> old.submitted_at
     or new.is_late <> old.is_late then
    raise exception 'Graders may only change marks and feedback' using errcode = '42501';
  end if;
  if new.marks_obtained is not null and new.marks_obtained > v_assignment.max_marks then
    raise exception 'Marks cannot exceed %', v_assignment.max_marks using errcode = '23514';
  end if;
  new.graded_by := auth.uid();
  new.graded_at := case when new.marks_obtained is null then null else now() end;
  return new;
end;
$$;

create trigger submissions_guard_write
  before insert or update on public.submissions
  for each row execute function public.guard_submission_write();

-- -----------------------------------------------------------------------------
-- quizzes: once any attempt exists only the publish flag may change, and the
-- questions / answer keys are frozen.
-- -----------------------------------------------------------------------------
create or replace function public.quiz_has_attempts(target_quiz_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.quiz_attempts where quiz_id = target_quiz_id)
$$;

revoke all on function public.quiz_has_attempts(uuid) from public, anon;
grant execute on function public.quiz_has_attempts(uuid) to authenticated, service_role;

create or replace function public.guard_quiz_update()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null or not public.quiz_has_attempts(old.id) then
    return new;
  end if;
  if new.course_id <> old.course_id
     or new.title <> old.title
     or new.description is distinct from old.description
     or new.time_limit_minutes <> old.time_limit_minutes
     or new.opens_at <> old.opens_at
     or new.closes_at <> old.closes_at
     or new.shuffle_questions <> old.shuffle_questions then
    raise exception 'This quiz already has attempts; only publishing can change' using errcode = 'P0001';
  end if;
  return new;
end;
$$;

create trigger quizzes_guard_update
  before update on public.quizzes
  for each row execute function public.guard_quiz_update();

create or replace function public.guard_quiz_question_write()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_quiz_id uuid;
begin
  if auth.uid() is null then
    return coalesce(new, old);
  end if;
  if tg_table_name = 'quiz_questions' then
    v_quiz_id := coalesce(new.quiz_id, old.quiz_id);
  else
    select qq.quiz_id into v_quiz_id
    from public.quiz_questions qq
    where qq.id = coalesce(new.question_id, old.question_id);
  end if;
  if v_quiz_id is not null and public.quiz_has_attempts(v_quiz_id) then
    raise exception 'This quiz already has attempts; questions are locked' using errcode = 'P0001';
  end if;
  return coalesce(new, old);
end;
$$;

create trigger quiz_questions_guard_write
  before insert or update or delete on public.quiz_questions
  for each row execute function public.guard_quiz_question_write();

create trigger quiz_answers_guard_write
  before insert or update or delete on public.quiz_answers
  for each row execute function public.guard_quiz_question_write();

-- -----------------------------------------------------------------------------
-- chat_messages: immutable except for a one-way soft delete.
-- -----------------------------------------------------------------------------
create or replace function public.guard_chat_message_update()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null then
    return new;
  end if;
  if new.body <> old.body
     or new.sender_id <> old.sender_id
     or new.course_id <> old.course_id
     or new.created_at <> old.created_at then
    raise exception 'Chat messages cannot be edited' using errcode = '42501';
  end if;
  if old.deleted_at is not null or new.deleted_at is null then
    raise exception 'Messages can only be deleted once' using errcode = '42501';
  end if;
  new.deleted_at := now();
  new.deleted_by := auth.uid();
  return new;
end;
$$;

create trigger chat_messages_guard_update
  before update on public.chat_messages
  for each row execute function public.guard_chat_message_update();

-- -----------------------------------------------------------------------------
-- complaints: status flow open -> in_review -> resolved | rejected, response
-- required to close, complainants may add exactly one follow-up comment.
-- -----------------------------------------------------------------------------
create or replace function public.guard_complaint_update()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null then
    return new;
  end if;

  if new.raised_by <> old.raised_by
     or new.course_id is distinct from old.course_id
     or new.category <> old.category
     or new.subject <> old.subject
     or new.description <> old.description
     or new.attachment_path is distinct from old.attachment_path
     or new.created_at <> old.created_at then
    raise exception 'Complaints cannot be edited after filing' using errcode = '42501';
  end if;

  if public.is_admin() then
    if new.follow_up is distinct from old.follow_up then
      raise exception 'Only the complainant can add a follow-up' using errcode = '42501';
    end if;
    if new.status <> old.status and not (
         (old.status = 'open' and new.status = 'in_review')
      or (old.status = 'in_review' and new.status in ('resolved', 'rejected'))
    ) then
      raise exception 'Invalid status change from % to %', old.status, new.status using errcode = '23514';
    end if;
    if new.status in ('resolved', 'rejected') and coalesce(btrim(new.admin_response), '') = '' then
      raise exception 'A response is required to resolve or reject a complaint' using errcode = '23514';
    end if;
    if new.status in ('resolved', 'rejected') and old.status not in ('resolved', 'rejected') then
      new.resolved_by := auth.uid();
      new.resolved_at := now();
    end if;
    return new;
  end if;

  -- Complainant: one follow-up comment only.
  if new.status <> old.status
     or new.admin_response is distinct from old.admin_response
     or new.resolved_by is distinct from old.resolved_by
     or new.resolved_at is distinct from old.resolved_at then
    raise exception 'Only administrators can change the status' using errcode = '42501';
  end if;
  if old.follow_up is not null then
    raise exception 'A follow-up has already been added' using errcode = 'P0001';
  end if;
  new.follow_up_at := now();
  return new;
end;
$$;

create trigger complaints_guard_update
  before update on public.complaints
  for each row execute function public.guard_complaint_update();


-- ===== migrations/0007_storage_realtime.sql =====
-- =============================================================================
-- 0007_storage_realtime.sql
-- Private storage buckets and Realtime publication.
--
-- Buckets are private and have NO storage.objects policies for the
-- "authenticated" role: browsers can never list, read or write objects
-- directly. The API authorizes every request, then uploads with the service
-- role and hands out 60-second signed URLs for downloads.
-- =============================================================================

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values
  (
    'resources', 'resources', false, 26214400,
    array[
      'application/pdf',
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      'application/vnd.openxmlformats-officedocument.presentationml.presentation',
      'application/zip',
      'image/png', 'image/jpeg', 'image/gif', 'image/webp'
    ]
  ),
  (
    'submissions', 'submissions', false, 26214400,
    array[
      'application/pdf',
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      'application/vnd.openxmlformats-officedocument.presentationml.presentation',
      'application/zip',
      'image/png', 'image/jpeg', 'image/gif', 'image/webp'
    ]
  ),
  (
    'complaint-attachments', 'complaint-attachments', false, 10485760,
    array[
      'application/pdf',
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      'image/png', 'image/jpeg', 'image/gif', 'image/webp'
    ]
  )
on conflict (id) do update
  set public             = excluded.public,
      file_size_limit    = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

-- -----------------------------------------------------------------------------
-- Realtime: chat, announcement badges and personal notifications.
-- Delivery is filtered by each table's SELECT policy (RLS).
-- -----------------------------------------------------------------------------
alter table public.chat_messages replica identity full;

do $$
declare
  t text;
begin
  if not exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    create publication supabase_realtime;
  end if;
  foreach t in array array['chat_messages', 'announcements', 'notifications'] loop
    if not exists (
      select 1 from pg_publication_tables
      where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t
    ) then
      execute format('alter publication supabase_realtime add table public.%I', t);
    end if;
  end loop;
end;
$$;


-- ===== migrations/0008_auth_helpers.sql =====
-- =============================================================================
-- 0008_auth_helpers.sql
-- Session revocation for the API (service role only). Used when an admin
-- deactivates a user or issues a temporary password, and after a password
-- reset/change so that every other device is signed out immediately.
-- Deleting a session cascades to its refresh tokens; access tokens tied to a
-- deleted session are rejected by auth.getUser().
-- =============================================================================

create or replace function public.revoke_user_sessions(
  target_user_id uuid,
  keep_session_id uuid default null
)
returns void
language sql
security definer
set search_path = ''
as $$
  delete from auth.sessions
  where user_id = target_user_id
    and (keep_session_id is null or id <> keep_session_id)
$$;

revoke all on function public.revoke_user_sessions(uuid, uuid) from public, anon, authenticated;
grant execute on function public.revoke_user_sessions(uuid, uuid) to service_role;


-- ===== migrations/0009_api_grants.sql =====
-- =============================================================================
-- 0009_api_grants.sql
-- Explicit table privileges for the Supabase API roles.
--
-- Row Level Security still decides which ROWS each user can see or change. These
-- grants only let the roles run the statements the API needs against the tables.
-- They are written out because a schema reset (supabase/reset-hosted.sql) removes
-- the default privileges that Supabase otherwise applies to new tables.
-- =============================================================================

grant usage on schema public to anon, authenticated, service_role;
grant select, insert, update, delete on all tables in schema public to authenticated, service_role;
grant usage, select on all sequences in schema public to authenticated, service_role;

-- Anonymous visitors never read or write application data.
revoke all on all tables in schema public from anon;

-- Users may only mark their own notifications as read.
revoke update on public.notifications from authenticated;
grant update (read_at) on public.notifications to authenticated;


